<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { CircleCheck, Document, Filter, Monitor, Search, Upload, Warning } from '@element-plus/icons-vue'
import NcLayout from '../components/NcLayout.vue'
import {
  ApiRequestError, commitDeviceImport, createDevice, createDeviceGroup, getDeviceGroups, getDeviceInventory,
  getDeviceInventoryDetail, getTerminalDevices, previewDeviceImport, updateDevice,
  type DeviceGroup, type DeviceImportPreview, type DeviceInventoryDetail, type DeviceInventoryItem, type DeviceInventoryPage, type TerminalDevice,
} from '../api/client'
import { useAuthStore } from '../stores/auth'

const route = useRoute(); const router = useRouter(); const auth = useAuthStore()
const result = ref<DeviceInventoryPage | null>(null); const groups = ref<DeviceGroup[]>([]); const profiles = ref<TerminalDevice[]>([])
const loading = ref(false); const unsupported = ref(false); const page = ref(1); const pageSize = ref(20)
const search = ref(String(route.query.q || '')); const status = ref(''); const siteId = ref('local'); const groupId = ref('')
const showEditor = ref(false); const showDetail = ref(false); const showGroup = ref(false); const showImport = ref(false)
const selected = ref<DeviceInventoryDetail | null>(null); const importPreview = ref<DeviceImportPreview | null>(null); const importCsv = ref('')
const form = reactive({ id: '', name: '', managementIp: '', vendor: '', model: '', deviceType: 'NETWORK_DEVICE', siteId: 'local', groupId: '', description: '', enabled: true, terminalProfileId: '' })
const groupForm = reactive({ siteId: 'local', name: '', description: '' })
const canWrite = computed(() => auth.user?.role === 'SUPERADMIN')
const rows = computed(() => result.value?.items || [])
const summary = computed(() => result.value?.summary || { totalRecords: 0, validDevices: 0, invalidRecords: 0, enabledDevices: 0, disabledDevices: 0, onlineDevices: 0, offlineDevices: 0, unknownStatus: 0 })

async function refresh(): Promise<void> {
  loading.value = true; unsupported.value = false
  try { result.value = await getDeviceInventory({ page: page.value, pageSize: pageSize.value, search: search.value, status: status.value, siteId: siteId.value, groupId: groupId.value }) }
  catch (cause) { unsupported.value = cause instanceof ApiRequestError && [404, 503].includes(cause.status); if (!unsupported.value) ElMessage.error('设备库存 API 读取失败') }
  finally { loading.value = false }
}
async function refreshGroups(): Promise<void> { try { groups.value = await getDeviceGroups(siteId.value) } catch { ElMessage.error('设备分组读取失败') } }
async function refreshProfiles(): Promise<void> { try { profiles.value = await getTerminalDevices() } catch { profiles.value = [] } }
function applyFilters(): void { page.value = 1; void refresh() }
function clearFilters(): void { search.value = ''; status.value = ''; groupId.value = ''; applyFilters() }
function formatTime(ms?: number | null): string { return ms ? new Date(ms).toLocaleString('zh-CN', { hour12: false }) : '—' }
function statusLabel(value: string): string { return ({ CONNECTED: '最近在线', DISCONNECTED: '最近离线', FAILED: '会话失败', CLOSED: '会话关闭', DISABLED: '已禁用', UNKNOWN: '状态未知' } as Record<string, string>)[value] || '未知' }
function statusClass(value: string): string { return value === 'CONNECTED' ? 'good' : value === 'DISABLED' || value === 'FAILED' ? 'bad' : value === 'UNKNOWN' ? 'neutral' : 'warn' }
function resetForm(): void { Object.assign(form, { id: '', name: '', managementIp: '', vendor: '', model: '', deviceType: 'NETWORK_DEVICE', siteId: siteId.value || 'local', groupId: '', description: '', enabled: true, terminalProfileId: '' }) }
function openCreate(): void { resetForm(); showEditor.value = true }
async function openEdit(row: DeviceInventoryItem): Promise<void> {
  try { selected.value = await getDeviceInventoryDetail(row.id); const item = selected.value.item; Object.assign(form, { id: item.id, name: item.name, managementIp: item.managementIp || item.managementAddress, vendor: item.vendor === '—' ? '' : item.vendor, model: item.model === '—' ? '' : item.model, deviceType: item.deviceType, siteId: item.siteId || 'local', groupId: item.groupId || '', description: selected.value.description, enabled: item.enabled, terminalProfileId: item.terminalProfileId || '' }); showEditor.value = true } catch { ElMessage.error('设备详情读取失败') }
}
async function openDetails(row: DeviceInventoryItem): Promise<void> { try { selected.value = await getDeviceInventoryDetail(row.id); showDetail.value = true } catch { ElMessage.error('设备详情读取失败') } }
function payload(): Record<string, unknown> { return { id: form.id || undefined, name: form.name, managementIp: form.managementIp, vendor: form.vendor, model: form.model, deviceType: form.deviceType, siteId: form.siteId, groupId: form.groupId || null, description: form.description, enabled: form.enabled, terminalProfileId: form.terminalProfileId || null } }
async function save(): Promise<void> {
  if (!canWrite.value) return
  try { if (form.id) await updateDevice(form.id, payload()); else await createDevice(payload()); ElMessage.success(form.id ? '设备已更新' : '设备已创建'); showEditor.value = false; await refresh() }
  catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : '设备保存失败') }
}
async function toggle(row: DeviceInventoryItem): Promise<void> {
  if (!canWrite.value) return
  try { const detail = await getDeviceInventoryDetail(row.id); const item = detail.item; await updateDevice(row.id, { id: row.id, name: item.name, managementIp: item.managementIp || item.managementAddress, vendor: item.vendor, model: item.model, deviceType: item.deviceType, siteId: item.siteId || 'local', groupId: item.groupId || null, description: detail.description, enabled: !item.enabled, terminalProfileId: item.terminalProfileId || null }); ElMessage.success(item.enabled ? '设备已禁用' : '设备已启用'); await refresh() }
  catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : '设备状态更新失败') }
}
function openInner(row: DeviceInventoryItem): void { if (row.terminalProfileId) router.push({ path: '/terminal', query: { deviceId: row.terminalProfileId } }); else ElMessage.warning('该设备尚未关联终端档案') }
async function createGroup(): Promise<void> { try { await createDeviceGroup(groupForm); ElMessage.success('分组已创建'); showGroup.value = false; groupForm.name = ''; groupForm.description = ''; await refreshGroups() } catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : '分组创建失败') } }
function onFile(event: Event): void { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { importCsv.value = String(reader.result || ''); void previewImport() }; reader.readAsText(file, 'UTF-8') }
async function previewImport(): Promise<void> { try { importPreview.value = await previewDeviceImport(importCsv.value); showImport.value = true } catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : 'CSV 预览失败') } }
async function commitImport(): Promise<void> { if (!importPreview.value || importPreview.value.conflictCount || importPreview.value.errorCount) return; try { const output = await commitDeviceImport(importPreview.value.previewId); ElMessage.success(`导入完成：新增 ${output.created}，更新 ${output.updated}`); showImport.value = false; importPreview.value = null; await refresh() } catch (cause) { ElMessage.error(cause instanceof Error ? cause.message : '导入提交失败') } }
function importFile(): void { document.getElementById('device-import-file')?.click() }
onMounted(async () => { await Promise.all([refresh(), refreshGroups(), refreshProfiles()]) })
</script>

<template>
  <NcLayout title="设备管理" description="设备库存与终端连接档案分离；所有写操作经服务端权限、CSRF 与审计校验">
    <template #actions>
      <el-button size="small" :loading="loading" @click="refresh">刷新</el-button><el-button size="small" @click="showGroup = true">分组管理</el-button><el-button size="small" @click="importFile"><el-icon><Upload /></el-icon>CSV 导入</el-button><el-button v-if="canWrite" type="primary" size="small" @click="openCreate">新增设备</el-button><input id="device-import-file" type="file" accept=".csv,text/csv" hidden @change="onFile" />
    </template>
    <div v-if="unsupported" class="card"><div class="empty-state"><div><el-icon><Monitor /></el-icon><strong>设备库存 API 尚未启用</strong><small>当前服务未提供设备查询能力；页面不会使用前端模拟数据。</small></div></div></div>
    <template v-else>
      <div class="inventory-summary"><span class="summary-chip"><b>{{ summary.totalRecords }}</b> 条设备</span><span class="summary-chip summary-chip--success"><b>{{ summary.enabledDevices }}</b> 已启用</span><span class="summary-chip"><b>{{ summary.disabledDevices }}</b> 已禁用</span><span class="summary-chip summary-chip--info"><b>{{ summary.onlineDevices }}</b> 最近在线</span><span class="summary-chip"><b>{{ summary.unknownStatus }}</b> 状态未知</span></div>
      <div v-if="summary.invalidRecords" class="data-quality-note"><el-icon><Warning /></el-icon>服务端报告 {{ summary.invalidRecords }} 条结构异常记录，异常不被隐藏。</div>
      <section class="card">
        <div class="filter-bar"><label class="global-search filter-input"><el-icon><Search /></el-icon><input v-model="search" placeholder="搜索名称、设备 ID、管理 IP、厂商" @keydown.enter="applyFilters" /></label><select v-model="groupId" aria-label="设备分组" @change="applyFilters"><option value="">全部分组</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select><select v-model="status" aria-label="设备状态" @change="applyFilters"><option value="">全部状态</option><option value="ENABLED">已启用</option><option value="DISABLED">已禁用</option><option value="ONLINE">最近在线</option><option value="OFFLINE">最近离线</option><option value="UNKNOWN">状态未知</option></select><button class="icon-button" type="button" title="清除筛选" @click="clearFilters"><el-icon><Filter /></el-icon></button><span class="filter-bar__grow" /><span class="muted">服务端分页 · 最新更新时间排序</span></div>
        <div v-loading="loading" class="table-wrap"><table class="data-table"><thead><tr><th>状态</th><th>设备名称 / ID</th><th>管理 IP</th><th>厂商 / 型号</th><th>类型</th><th>局点 / 分组</th><th>终端档案</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="device in rows" :key="device.id" :class="{ 'is-invalid': !device.isValid }" @dblclick="openDetails(device)"><td><span :class="['state-pill', statusClass(device.connectionStatus)]"><i class="status-dot" />{{ statusLabel(device.connectionStatus) }}</span></td><td><span class="device-name">{{ device.name }}</span><span class="device-subline mono">{{ device.deviceId || device.id }}<span v-if="!device.isValid" class="device-quality">· {{ device.qualityIssues.join(' / ') }}</span></span></td><td class="device-address">{{ device.managementIp || device.managementAddress }}</td><td>{{ device.vendor }}<span class="device-subline">{{ device.model }}</span></td><td>{{ device.deviceType }}</td><td>{{ device.site }}<span class="device-subline">{{ device.group }}</span></td><td><span :class="['state-pill', device.terminalProfileId ? 'good' : 'neutral']">{{ device.terminalProfileId ? '已关联' : '未关联' }}</span></td><td>{{ formatTime(device.updatedAt || device.lastSeenMs) }}</td><td><div class="table-actions"><el-button text size="small" @click="openDetails(device)">详情</el-button><el-button v-if="canWrite" text size="small" @click="openEdit(device)">编辑</el-button><el-button v-if="canWrite" text size="small" @click="toggle(device)">{{ device.enabled ? '禁用' : '启用' }}</el-button><el-button text size="small" :disabled="!device.terminalProfileId" @click="openInner(device)">终端</el-button></div></td></tr><tr v-if="!rows.length"><td colspan="9"><div class="empty-state"><div><el-icon><Document /></el-icon><strong>{{ search || status || groupId ? '没有符合条件的设备' : '暂无设备' }}</strong><small>新增设备或导入 CSV 后，数据会从 Catalog 真实读取。</small></div></div></td></tr></tbody></table></div>
        <div class="pagination-bar"><span>第 {{ page }} 页 · 每页 {{ pageSize }} 条 · 共 {{ result?.total || 0 }} 条</span><div class="toolbar"><select v-model.number="pageSize" @change="page = 1; refresh()"><option :value="20">20 / 页</option><option :value="50">50 / 页</option><option :value="100">100 / 页</option></select><el-button size="small" :disabled="page <= 1" @click="page--; refresh()">上一页</el-button><el-button size="small" :disabled="!result?.hasMore" @click="page++; refresh()">下一页</el-button></div></div>
      </section>
    </template>
    <div class="section-label">数据与安全口径</div><div class="card card--flat"><div class="card__body overview-footer"><span><el-icon><CircleCheck /></el-icon>设备库存与 h3c_device_profiles 分离，终端历史按原 profile ID 保留</span><span><el-icon><CircleCheck /></el-icon>启用状态由服务端同步到已关联终端档案</span><span><el-icon><Warning /></el-icon>CSV 不接受密码、凭据或私钥列，导入先预览再原子提交</span></div></div>
    <el-dialog v-model="showEditor" :title="form.id ? '编辑设备' : '新增设备'" width="660px"><div class="form-grid"><label class="form-field"><span>设备 ID</span><input v-model="form.id" :disabled="!!form.id" placeholder="留空自动生成" /></label><label class="form-field"><span>设备名称</span><input v-model="form.name" required /></label><label class="form-field"><span>管理 IP</span><input v-model="form.managementIp" placeholder="192.0.2.10" /></label><label class="form-field"><span>厂商</span><input v-model="form.vendor" /></label><label class="form-field"><span>型号</span><input v-model="form.model" /></label><label class="form-field"><span>设备类型</span><input v-model="form.deviceType" /></label><label class="form-field"><span>局点</span><input v-model="form.siteId" disabled /></label><label class="form-field"><span>分组</span><select v-model="form.groupId"><option value="">未分组</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label class="form-field"><span>终端档案</span><select v-model="form.terminalProfileId"><option value="">不关联</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{ profile.host }} · {{ profile.username }}</option></select></label><label class="form-field"><span>描述</span><input v-model="form.description" /></label><label class="form-field" style="align-items:center"><span>启用</span><input v-model="form.enabled" type="checkbox" /></label></div><template #footer><el-button @click="showEditor = false">取消</el-button><el-button type="primary" :loading="loading" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="showDetail" title="设备详情 / 审计" width="760px"><template v-if="selected"><div class="detail-grid"><div><span>设备名称</span><b>{{ selected.item.name }}</b></div><div><span>设备 ID</span><b class="mono">{{ selected.item.id }}</b></div><div><span>管理 IP</span><b class="mono">{{ selected.item.managementIp || selected.item.managementAddress }}</b></div><div><span>厂商 / 型号</span><b>{{ selected.item.vendor }} / {{ selected.item.model }}</b></div><div><span>局点 / 分组</span><b>{{ selected.item.site }} / {{ selected.item.group }}</b></div><div><span>终端档案</span><b>{{ selected.terminalProfileId || '未关联' }}</b></div><div><span>创建时间</span><b>{{ formatTime(selected.createdMs) }}</b></div><div><span>更新时间</span><b>{{ formatTime(selected.updatedMs) }}</b></div></div><p class="muted">{{ selected.description || '无描述' }}</p><div v-if="selected.item.qualityIssues.length" class="data-quality-note"><el-icon><Warning /></el-icon>{{ selected.item.qualityIssues.join(' / ') }}</div><h3>最近终端会话</h3><div v-if="!selected.recentSessions.length" class="muted">暂无持久化终端历史</div><div v-for="session in selected.recentSessions" :key="session.id" class="overview-footer"><span>{{ formatTime(session.startedMs) }} · {{ session.protocol }}</span><span>{{ session.state }} · {{ session.recordingStatus }}</span></div><h3>审计记录</h3><div v-for="audit in selected.auditEvents" :key="audit.id" class="overview-footer"><span>{{ formatTime(audit.atMs) }} · {{ audit.action }}</span><span>{{ audit.outcome }}</span></div></template></el-dialog>
    <el-dialog v-model="showGroup" title="设备分组管理" width="520px"><div class="form-grid"><label class="form-field"><span>局点</span><input v-model="groupForm.siteId" /></label><label class="form-field"><span>分组名称</span><input v-model="groupForm.name" /></label><label class="form-field"><span>描述</span><input v-model="groupForm.description" /></label></div><div class="overview-footer" style="margin-top:16px"><span v-for="group in groups" :key="group.id">{{ group.name }} · {{ group.deviceCount }} 台</span></div><template #footer><el-button @click="showGroup = false">关闭</el-button><el-button v-if="canWrite" type="primary" @click="createGroup">新增分组</el-button></template></el-dialog>
    <el-dialog v-model="showImport" title="CSV 导入预览" width="820px"><p class="muted">预览不会写入数据库；只有无冲突、明确确认后才会执行单事务提交。支持 create / update，任何错误都会阻止整批写入。</p><div v-if="importPreview" class="inventory-summary"><span class="summary-chip"><b>{{ importPreview.totalRows }}</b> 行</span><span class="summary-chip summary-chip--success"><b>{{ importPreview.createCount }}</b> 新增</span><span class="summary-chip summary-chip--info"><b>{{ importPreview.updateCount }}</b> 更新</span><span class="summary-chip summary-chip--danger"><b>{{ importPreview.conflictCount + importPreview.errorCount }}</b> 冲突/错误</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>行</th><th>动作</th><th>名称</th><th>管理 IP</th><th>说明</th></tr></thead><tbody><tr v-for="row in importPreview?.rows || []" :key="row.line"><td>{{ row.line }}</td><td>{{ row.action }}</td><td>{{ row.name }}</td><td>{{ row.managementIp }}</td><td>{{ row.detail }}</td></tr></tbody></table></div><template #footer><el-button @click="showImport = false">取消</el-button><el-button type="primary" :disabled="!importPreview || !!(importPreview.conflictCount || importPreview.errorCount)" @click="commitImport">确认原子导入</el-button></template></el-dialog>
  </NcLayout>
</template>
